  <form id="signup-form" method="post" accept-charset="utf-8">
    <div class="field">
      <label for="name">Full name</label>
      <input id="name" name="name" type="text" autocomplete="name" dir="auto" required
             aria-describedby="name-error">
      <p class="error" id="name-error" aria-live="polite"></p>
    </div>

