<script>
(function () {
  'use strict';

  var form = document.getElementById('signup-form');
  var statusEl = document.getElementById('form-status');

  // Validation is done here; the "required" attributes remain as a fallback without JavaScript.
  form.noValidate = true;

  /* ---------- Domain names ---------- */

  // These two patterns are only ever applied to the A-label (ASCII, lower-case) form of a
  // name, i.e. AFTER the IDNA conversion. Unicode domains are converted, never rejected.
  var LDH_LABEL = /^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/;
  // A TLD is two or more letters (no upper bound other than the 63-octet label limit)
  // or an "xn--" A-label such as xn--p1ai (.рф).
  var TLD = /^(?:[a-z]{2,}|xn--[a-z0-9-]+)$/;

  function isAsciiHostname(host) {
    if (host.length > 253) return false;
    var labels = host.split('.');
    if (labels.length < 2) return false;
    for (var i = 0; i < labels.length; i++) {
      if (labels[i].length > 63 || !LDH_LABEL.test(labels[i])) return false;
    }
    return TLD.test(labels[labels.length - 1]);
  }

  // Converts a domain name typed by the user (U-labels and/or A-labels, any case) to its
  // A-label form with the browser's UTS #46 implementation. Returns null if it is not a
  // valid domain name.
  function domainToAscii(domain) {
    if (!domain || /[\s\u0000-\u001f\u007f\/\\?#:%@\[\]]/.test(domain)) return null;
    var ascii;
    try {
      ascii = new URL('http://' + domain + '/').hostname;
    } catch (e) {
      return null;
    }
    return isAsciiHostname(ascii) ? ascii : null;
  }

  /* ---------- Field validators: return { error } or { value[, ascii] } ---------- */

  function validateName(raw) {
    var value = raw.trim();
    if (!value) return { error: 'Enter your full name.' };
    if (!/\p{L}/u.test(value)) return { error: 'Your name should contain at least one letter.' };
    return { value: value };
  }

  function validateEmail(raw) {
    var value = raw.trim();
    if (!value) return { error: 'Enter your email address.' };
    if (/[\s\u0000-\u001f\u007f]/.test(value)) return { error: 'An email address cannot contain spaces.' };

    var parts = value.split('@');
    if (parts.length < 2) return { error: 'An email address needs an @, like name@example.com.' };
    if (parts.length > 2) return { error: 'An email address can only contain one @.' };

    var local = parts[0];
    var domain = parts[1];
    if (!local) return { error: 'Add the part before the @.' };
    if (!domain) return { error: 'Add the domain after the @, like example.com.' };

    var asciiDomain = domainToAscii(domain);
    if (!asciiDomain) {
      return { error: 'The part after the @ should be a domain name, like example.com.' };
    }
    // The local part is kept exactly as typed (it may contain Unicode, +, ' …).
    return { value: value, ascii: local + '@' + asciiDomain };
  }

  function validateWebsite(raw) {
    var value = raw.trim();
    if (!value) return { value: '', ascii: '' }; // optional field
    if (/\s/.test(value)) return { error: 'A web address cannot contain spaces.' };

    var candidate = value.indexOf('://') === -1 ? 'https://' + value : value;
    var url;
    try {
      url = new URL(candidate);
    } catch (e) {
      return { error: 'Enter a web address, like example.com or https://example.com.' };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'The web address should start with http:// or https://.' };
    }
    if (url.username || url.password) {
      return { error: 'The web address should not contain a user name or password.' };
    }
    // url.hostname is already in A-label form; a single trailing dot is legal in a URL.
    if (!isAsciiHostname(url.hostname.replace(/\.$/, ''))) {
      return { error: 'The web address needs a valid domain name, like example.com.' };
    }
    return { value: value, ascii: url.href };
  }

  function validatePassword(raw) {
    if (!raw) return { error: 'Choose a password.' };
    if (Array.from(raw).length < 8) return { error: 'Use at least 8 characters.' };
    return { value: raw };
  }

  /* ---------- Wiring ---------- */

  var fields = [
    { id: 'name', validate: validateName },
    { id: 'email', validate: validateEmail, asciiId: 'email_ascii' },
    { id: 'website', validate: validateWebsite, asciiId: 'website_ascii' },
    { id: 'password', validate: validatePassword }
  ];

  fields.forEach(function (field) {
    field.input = document.getElementById(field.id);
    field.errorEl = document.getElementById(field.id + '-error');
    field.asciiEl = field.asciiId ? document.getElementById(field.asciiId) : null;

    // Check when leaving a field that has been filled in…
    field.input.addEventListener('blur', function () {
      if (field.input.value !== '' || field.input.getAttribute('aria-invalid') === 'true') {
        check(field);
      }
    });
    // …and clear the error as soon as the value becomes valid.
    field.input.addEventListener('input', function () {
      statusEl.textContent = '';
      if (field.input.getAttribute('aria-invalid') === 'true') check(field);
    });
  });

  function check(field) {
    var result = field.validate(field.input.value);
    if (result.error) {
      field.input.setAttribute('aria-invalid', 'true');
      field.errorEl.textContent = result.error;
    } else {
      field.input.removeAttribute('aria-invalid');
      field.errorEl.textContent = '';
    }
    if (field.asciiEl) field.asciiEl.value = result.error ? '' : result.ascii;
    return result;
  }

  form.addEventListener('submit', function (event) {
    var firstInvalid = null;
    var results = {};

    fields.forEach(function (field) {
      var result = check(field);
      results[field.id] = result;
      if (result.error && !firstInvalid) firstInvalid = field.input;
    });

    if (firstInvalid) {
      event.preventDefault();
      statusEl.textContent = '';
      firstInvalid.focus();
      return;
    }

    // With an "action" attribute the browser now submits the form. Without one (standalone
    // page), show a confirmation instead.
    if (!form.hasAttribute('action')) {
      event.preventDefault();
      statusEl.textContent = 'Thanks, ' + results.name.value + '. Your details are valid and ready to send.';
    }
  });

  var toggle = document.getElementById('toggle-password');
  var password = document.getElementById('password');
  toggle.addEventListener('click', function () {
    var show = password.type === 'password';
    password.type = show ? 'text' : 'password';
    toggle.textContent = show ? 'Hide' : 'Show';
    toggle.setAttribute('aria-pressed', String(show));
  });
})();
</script>
